product_names = [p['Product Name'] for p in products]
revenue = {p['Product Name']: p['Revenue'] for p in products}
inventory = {p['Product Name']: p['Initial Inventory'] for p in products}
demand = {p['Product Name']: p['Demand'] for p in products}
for name in product_names:
    if name not in revenue or name not in inventory or name not in demand:
        raise ValueError(f'Missing data for product {name}')
m = gp.Model('Fashion_Revenue_Max')
x_vars = m.addVars(product_names, vtype=GRB.INTEGER, lb=0, name='')
m.setObjective(gp.quicksum((revenue[name] * x_vars[name] for name in product_names)), GRB.MAXIMIZE)
m.addConstrs((x_vars[name] <= min(inventory[name], demand[name]) for name in product_names), name='')
m.setParam('MIPGap', 0.0001)
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in x_vars.values():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')